from pathlib import Path

path = Path("scripts/run-node-31-file-protocol-runtime.mjs")
text = path.read_text()

start_marker = '  console.log("NODE-31 file protocol: reactivating final unpacked extension after permission change");'
end_marker = '  console.log(\n    JSON.stringify('
start = text.find(start_marker)
end = text.find(end_marker, start)
if start < 0 or end < 0 or end <= start:
    raise SystemExit("file protocol production-flow anchors missing")

new_flow = '''  console.log("NODE-31 file protocol: reactivating final unpacked extension after permission change");\n  await reactivateUnpackedExtension(browserClient, extensionRoot, extensionId);\n  await waitFor(\n    primaryClient,\n    `new Promise((resolvePromise, reject) => {\n      chrome.developerPrivate.getExtensionInfo(\n        ${JSON.stringify(extensionId)},\n        (info) => chrome.runtime.lastError\n          ? reject(new Error(chrome.runtime.lastError.message))\n          : resolvePromise(info.fileAccess?.isEnabled === true && info.fileAccess?.isActive === true),\n      );\n    })`,\n    "Explicit file access was not retained after unpacked extension reactivation",\n  );\n\n  console.log("NODE-31 file protocol: loading real file fixture for packaged popup capture");\n  await navigate(primaryClient, fixtureUrl, "file protocol fixture for packaged popup capture");\n  await browserClient.send("Target.activateTarget", { targetId: primary.targetId });\n  await delay(100);\n  assert(\n    await evaluate(\n      primaryClient,\n      `document.querySelector('[data-node31-role="file-protocol-proof"]')?.textContent?.includes("NODE-31 explicit file URL permission runtime proof") === true`,\n    ),\n    "File protocol fixture content did not load after explicit permission enable",\n  );\n\n  const popupUrl = `chrome-extension://${extensionId}/popup.html`;\n  console.log("NODE-31 file protocol: loading final packaged popup in real Chrome");\n  const popup = await createPageSession(browserClient, popupUrl, "final packaged popup");\n  const popupClient = popup.client;\n  assert(\n    (await evaluate(popupClient, "location.href")) === popupUrl,\n    "Loaded extension page does not match final packaged popup",\n  );\n  await waitFor(\n    popupClient,\n    `document.querySelector("#responsive-capability")?.textContent !== "Checking…"`,\n    "Final popup production script did not connect to the service worker",\n  );\n  assert(\n    (await evaluate(popupClient, `chrome.extension.isAllowedFileSchemeAccess()`)) === true,\n    "Final popup did not retain explicitly enabled file access",\n  );\n\n  await browserClient.send("Target.activateTarget", { targetId: primary.targetId });\n  await delay(100);\n  const activeTabUrl = await evaluate(\n    popupClient,\n    `chrome.tabs.query({ active: true, currentWindow: true }).then((tabs) => tabs[0]?.url ?? null)`,\n  );\n  assert(activeTabUrl === fixtureUrl, `Final popup active file tab mismatch: ${activeTabUrl}`);\n\n  assert(\n    (await evaluate(\n      popupClient,\n      `document.querySelector("#capture-full-page") instanceof HTMLButtonElement`,\n    )) === true,\n    "Final popup is missing the Full page DOM control",\n  );\n  console.log("NODE-31 file protocol: clicking final popup Full page DOM control");\n  assert(\n    (await evaluate(\n      popupClient,\n      `(() => {\n        const button = document.querySelector("#capture-full-page");\n        if (!(button instanceof HTMLButtonElement) || button.disabled) return false;\n        button.click();\n        return true;\n      })()`,\n    )) === true,\n    "Final popup Full page DOM control was not clickable",\n  );\n  await waitFor(\n    popupClient,\n    `document.querySelector("#job-details")?.textContent === "Capturing the current rendered page…" || document.querySelector("#job-status")?.dataset.status === "completed"`,\n    "Final popup DOM click did not enter the production capture path",\n  );\n\n  let popupState = null;\n  for (let attempt = 0; attempt < 2400; attempt += 1) {\n    popupState = await evaluate(\n      popupClient,\n      `({\n        status: document.querySelector("#job-status")?.dataset.status ?? null,\n        details: document.querySelector("#job-details")?.textContent ?? null,\n        jobId: document.querySelector("#export-wtf")?.dataset.jobId ?? null,\n      })`,\n    );\n    if (popupState?.status === "completed" || popupState?.status === "failed") break;\n    await delay(25);\n  }\n  assert(\n    popupState?.status === "completed",\n    `Production file capture did not complete through final popup: ${popupState?.details ?? popupState?.status}`,\n  );\n  assert(\n    typeof popupState?.jobId === "string" && popupState.jobId.length > 0,\n    "Completed popup capture did not expose a job id",\n  );\n\n  console.log("NODE-31 file protocol: reading completed production job state");\n  const jobResponse = await evaluate(\n    popupClient,\n    `(async () => chrome.runtime.sendMessage({ type: "W2F_GET_JOB_STATE" }))()`,\n  );\n  assert(jobResponse?.ok === true, "Production job-state request failed after popup capture");\n  const job = jobResponse?.data;\n  assert(job?.jobId === popupState.jobId, "Popup job id does not match persisted production job");\n  assert(job?.mode === "full-page", "Production capture job mode mismatch");\n  assert(job?.status === "completed", `Production file capture job is not completed: ${job?.status}`);\n  assert(job?.source?.provider === "file-tab", "Completed job lost file-tab source provider");\n  assert(job?.source?.sourceType === "file", "Completed job lost file source type");\n  assert(job?.source?.sourceUrl === fixtureUrl, "Completed job lost the real file URL");\n  assert(job?.source?.offline === true, "Completed job lost offline file semantics");\n  assert(job?.page?.url === fixtureUrl, "Completed job page URL mismatch");\n  assert(\n    job?.capture?.adapter === "standard" || job?.capture?.adapter === "cdp",\n    `Completed job did not report a production capture adapter: ${job?.capture?.adapter}`,\n  );\n  assert((job?.capture?.nodeCount ?? 0) > 0, "Completed file capture contains no nodes");\n  assert(\n    typeof job?.capture?.storageKey === "string" && job.capture.storageKey.length > 0,\n    "Completed file capture did not persist a RawSnapshot",\n  );\n\n  console.log("NODE-31 file protocol: reading persisted RawSnapshot from production snapshot store");\n  const snapshot = await evaluate(\n    popupClient,\n    `(async () => {\n      const module = await import(chrome.runtime.getURL("runtime/snapshot-store.js"));\n      return module.readRawSnapshot(${JSON.stringify(popupState.jobId)});\n    })()`,\n  );\n  assert(snapshot, "Production snapshot store did not return the completed RawSnapshot");\n  assert(snapshot?.url === fixtureUrl, "Persisted file snapshot URL mismatch");\n  assert(snapshot?.title === "NODE-31 File Protocol Runtime", "Persisted file snapshot title mismatch");\n  assert(\n    snapshot?.nodes?.some(\n      (node) =>\n        node.source?.attributes?.["data-node31-role"] === "file-protocol-proof" &&\n        node.textContent?.includes("NODE-31 explicit file URL permission runtime proof"),\n    ),\n    "Persisted file snapshot is missing editable fixture text",\n  );\n\n'''
text = text[:start] + new_flow + text[end:]

text = text.replace(
    '        version: "1.1.0",\n        evidenceType: "node31-file-protocol-browser-runtime",',
    '        version: "1.3.0",\n        evidenceType: "node31-file-protocol-browser-runtime",',
    1,
)

artifact_anchor = '        extensionArtifact: "apps/browser-extension/dist",\n'
artifact_replacement = '''        extensionArtifact: "apps/browser-extension/dist",\n        popupArtifact: "apps/browser-extension/dist/popup.html",\n        popupRuntimeArtifact: "apps/browser-extension/dist/runtime/popup.js",\n        serviceWorkerArtifact: "apps/browser-extension/dist/runtime/service-worker.js",\n        snapshotStoreArtifact: "apps/browser-extension/dist/runtime/snapshot-store.js",\n'''
if artifact_anchor in text:
    text = text.replace(artifact_anchor, artifact_replacement, 1)
elif artifact_replacement not in text:
    raise SystemExit("packaged popup evidence artifact anchor missing")

assertions_start_marker = '        assertions: [\n'
assertions_end_marker = '        ],\n        provesP0Items:'
assertions_start = text.find(assertions_start_marker, text.find(end_marker))
assertions_end = text.find(assertions_end_marker, assertions_start)
if assertions_start < 0 or assertions_end < 0:
    raise SystemExit("file protocol evidence assertion block anchors missing")

assertions_block = '''        assertions: [\n          "built-manifest-declares-file-scheme-host-permission",\n          "unpacked-extension-loaded-through-modern-cdp-in-real-chrome",\n          "chrome-management-state-explicitly-disables-file-access",\n          "chrome-management-state-explicitly-enables-file-access",\n          "real-file-url-fixture-loads-after-explicit-permission",\n          "final-packaged-popup-loads-in-real-chrome",\n          "final-popup-production-script-connects-to-service-worker",\n          "final-popup-retains-enabled-file-access",\n          "final-popup-observes-active-file-url",\n          "final-popup-full-page-dom-control-is-wired",\n          "final-popup-dom-click-enters-production-capture-path",\n          "production-full-page-job-completes-on-file-url",\n          "completed-job-preserves-file-source-and-page-url",\n          "completed-job-uses-production-capture-adapter",\n          "completed-job-persists-raw-snapshot",\n          "persisted-raw-snapshot-preserves-file-url-and-title",\n          "persisted-raw-snapshot-preserves-editable-text-structure",\n'''
text = text[:assertions_start] + assertions_block + text[assertions_end:]

path.write_text(text)
print("NODE-31 packaged-popup file protocol candidate materialized in working tree.")
